export const projects: Project[] = [
 { id:'abi', name:'ABI', category:'Runtime', role:'Orchestration & runtime', language:'Rust', description:'A local AI runtime with inspectable orchestration and explicit capability reporting.', overview:'ABI brings local AI service orchestration, runtime primitives, and WDBX semantic storage into a nightly Rust framework. Its documentation makes a useful distinction: reporting an available backend is not the same as proving that its native kernels are executing.', documented:['Local service orchestration and runtime primitives','CLI and MCP interfaces described by the repository','Capability reporting with an explicit CPU fallback'], limits:'Native CUDA, Vulkan, and ANE kernel acceleration is not established by the README. The website benchmark dashboard uses synthetic samples. Browser planning is not autonomous browser execution. No backend tests were rerun for this preview.', repo:'https://github.com/donaldfilimon/abi', guide:'abi-runtime', sources:['abi','claims'] },
 { id:'wdbx', name:'WDBX', category:'Storage', role:'Semantic memory & retrieval', language:'ABI workspace', description:'Semantic storage and retrieval in the ABI ecosystem, with scoped persistence contracts.', overview:'WDBX is the semantic-storage component associated with ABI. The README describes vector retrieval, persistence, and a set of storage contracts. This website explains those boundaries; it is not connected to a running WDBX database.', documented:['Ordered search and hybrid-ranking coverage reported upstream','Segment and WAL recovery, compaction, and metadata contracts','Temporal-graph snapshot restoration described by the README'], limits:'Reported test coverage is not a benchmark or an independent rerun. A write may be skipped, unavailable, or unsuccessful; success must not be fabricated. Production scaling and security guarantees are not established here.', repo:'https://github.com/donaldfilimon/abi', guide:'wdbx', sources:['abi','wdbx'] },
 { id:'abbey', name:'Abbey', category:'Companion', role:'Interaction & identity', language:'Companion project', description:'A companion direction built around understandable interaction and a claims-ledger discipline.', overview:'ABI describes Abbey as its primary companion profile and points to a separate companion interface. Aviva is the direct expert mode; ABI is the orchestration and governance layer. These roles are not evidence of three independently deployed products.', documented:['Companion relationship referenced by the ABI README','Separate interaction roles for Abbey, Aviva, and ABI','An identity specification linked from upstream documentation'], limits:'The companion repository is referenced by ABI, but its build and deployment were not assessed for this preview. A profile name does not establish model quality, autonomy, consciousness, or access to personal records.', repo:'https://github.com/donaldfilimon/abbey', guide:'identity', sources:['abi','identity'] },
 { id:'gama', name:'Gama', category:'Framework', role:'Declarative application UI', language:'Swift', description:'A modular Swift UI framework organized around a retained render tree and explicit scenes.', overview:'Gama describes a common retained render tree with terminal, Apple, WebAssembly, C/Android, MLIR, and Embedded Swift integrations. It is a separate application-framework project, not a dependency that this website assumes is deployed inside ABI.', documented:['Scenes, state, layout, and events in GamaCore','Dedicated terminal, Apple, WebAssembly, and embedding modules','A retained render tree and explicit primary-scene model'], limits:'The README describes integrations; it does not establish that every platform passed acceptance in this review. Consult the actual revision for toolchain prerequisites, build commands, and platform-specific requirements.', repo:'https://github.com/donaldfilimon/gama', guide:'gama', sources:['gama'] }
];
export interface Section { id: string; title: string; paragraphs: string[]; bullets?: string[]; code?: string; note?: string; }
export interface Article { slug: string; title: string; description: string; group: string; sections: Section[]; sources: SourceId[]; }
export const articles: Article[] = [
 { slug:'', title:'Documentation', description:'A practical field guide to the MLAI ecosystem. Follow the ideas back to the source.', group:'Start here', sources:['platform','abi','gama'], sections:[
  {id:'choose-a-direction',title:'Choose a direction',paragraphs:['Start with the problem you want to understand. ABI is the runtime and orchestration project. WDBX is semantic storage associated with ABI. Abbey is the companion identity and interaction direction. Gama is a separate Swift application-framework project.','The guides connect those roles without pretending that a conceptual map is a production deployment. Choose a project, read its scope, then inspect the source instructions for the revision you intend to use.'],bullets:['New to the ecosystem? Read Getting started.','Evaluating a capability? Read Evidence and limitations.','Working in the existing website? Read Platform and site architecture.']},
  {id:'read-the-evidence',title:'Read the evidence',paragraphs:['A source description tells you what the project documents. Reported test coverage tells you what its authors say the tests cover. A measured result needs a specific artifact, method, environment, date, and revision. These are different kinds of evidence.','This preview does not execute ABI, run a model, or open a WDBX store. It publishes no measured performance claims. Source references below identify what was reviewed and what is simply an upstream reference.']},
  {id:'use-the-guides',title:'Use the guides',paragraphs:['Search with the documentation search control or Control/Command + K. Search runs against the articles bundled with this site; it is not an AI answer service and does not send the query to a server.','Each guide has stable headings, source references, and adjacent-page navigation. The copy controls copy documentation, not the result of a command run. Follow upstream prerequisites before executing anything in your own checkout.']}
 ]},
 {slug:'getting-started',title:'Getting started',description:'Choose a project, prepare its checkout, and validate the actual revision you will use.',group:'Start here',sources:['abi','platform','gama'],sections:[
  {id:'start-with-a-checkout',title:'Start with a checkout',paragraphs:['The source repository is the starting point, not a download button that promises a working runtime on every machine. Read the current README, toolchain requirements, and workspace setup before running project commands.','For ABI, a checkout is a useful first step. The repository may have sibling-workspace or environment requirements, so cloning alone is not a guarantee that a build will succeed.'],code:'git clone https://github.com/donaldfilimon/abi.git\ncd abi'},
  {id:'use-the-project-wrapper',title:'Use the project wrapper',paragraphs:['ABI documents a nightly Rust workflow through its tools/cargo.sh wrapper. Use the wrapper rather than substituting a different local Cargo toolchain. Its check script is the primary validation gate described by the README.'],code:'./tools/cargo.sh --version\n./tools/check.sh\n./tools/cargo.sh build -p abi-cli',note:'Documentation commands, not executed results. Prepare the upstream toolchain and workspace first.'},
  {id:'inspect-before-connecting',title:'Inspect before connecting',paragraphs:['Once your own build succeeds, the README describes local inspection commands for available backends and scheduler state. A backend name is not proof that hardware acceleration is active. Read the capability flags and their limitations.'],code:'./target/debug/abi backends\n./target/debug/abi scheduler status'},
  {id:'keep-checks-scoped',title:'Keep checks scoped',paragraphs:['Record the revision, machine, toolchain, command, and result when you verify a behavior. A passing local build does not establish production latency, cross-host behavior, or another platform’s acceptance.','Gama and the existing MLAI website have their own build instructions. Do not run ABI commands inside those projects. This preview neither creates credentials nor starts a live provider connection.']}
 ]},
 {slug:'architecture',title:'Project architecture',description:'Understand the boundaries between runtime, memory, interaction, and application UI.',group:'Start here',sources:['abi','identity','gama','platform'],sections:[
  {id:'a-map-not-a-deployment',title:'A map, not a deployment',paragraphs:['The homepage diagram explains relationships: Abbey is a companion direction; ABI provides orchestration and runtime foundations; WDBX supplies semantic storage associated with that runtime. Selecting a layer changes an explanation, not a running system.','Cloud backends are optional according to the ABI README. The diagram does not imply that all integrations are configured, that every data path is implemented, or that a production cluster has been verified.']},
  {id:'products-and-personas',title:'Products and personas',paragraphs:['ABI as a software product and Abi as a governance persona are different axes. Likewise, Aviva is described as a direct expert mode, not an independently verified standalone repository. Keep those distinctions visible in copy, APIs, and UI labels.','The existing MLAI contracts distinguish product accents from persona colors. This design uses violet for the ABI product and does not use that color to assert a persona identity.']},
  {id:'gama-is-a-separate-track',title:'Gama is a separate track',paragraphs:['Gama focuses on declarative application UI in Swift. Its retained-tree and scene model addresses application rendering, not the Rust runtime’s backend selection or WDBX persistence.','An integration may be an interesting future idea, but an attractive diagram is not evidence that it already exists. Proposed relationships should remain labeled until a concrete implementation and appropriate verification support them.']}
 ]},
 {slug:'abi-runtime',title:'ABI runtime',description:'Local orchestration, observable capabilities, and the limits of a runtime description.',group:'Systems',sources:['abi','claims'],sections:[
  {id:'runtime-foundations',title:'Runtime foundations',paragraphs:['The reviewed README describes ABI as a nightly Rust framework for local AI service orchestration, WDBX semantic storage, and runtime primitives. It explicitly says that the older Zig tree was removed.','CLI and MCP surfaces are documented alongside local inspection commands. Their presence does not independently establish successful live-provider dispatch, general model quality, or every transport integration. Use the relevant contract and current source when evaluating one of those behaviors.']},
  {id:'capability-is-not-execution',title:'Capability is not execution',paragraphs:['A capability table can identify a preferred backend without proving that its native kernels are linked. ABI’s README requires honest accelerated=false reporting in that situation and describes deterministic CPU SIMD fallback.','Do not turn that fallback into a GPU speedup claim. CUDA, Vulkan, and ANE native-kernel claims require their own evidence. Hardware availability, linking, execution, correctness, and performance are separate questions.']},
  {id:'demos-have-boundaries',title:'Demos have boundaries',paragraphs:['The project’s benchmark dashboard renders synthetic sample data. It can demonstrate a presentation format, but those charts are not measured throughput, latency, or accuracy. The small neural demonstration is not a production LLM.','The README also distinguishes local browser planning from actual autonomous browser execution. Treat plans and reference surfaces as what they are, and follow the documented external-integration boundary rather than claiming an embedded browser.']}
 ]},
 {slug:'wdbx',title:'WDBX storage',description:'Semantic retrieval and persistence, without turning scoped contracts into unlimited guarantees.',group:'Systems',sources:['abi','wdbx'],sections:[
  {id:'retrieval-has-a-scope',title:'Retrieval has a scope',paragraphs:['WDBX is the semantic-storage component associated with the ABI workspace. Vector retrieval helps find stored representations related to a query; similarity does not by itself establish factual correctness or permission to reveal a record.','The ABI README reports contract coverage for ordered vector-search results, metadata round trips, segment and WAL recovery, compaction, temporal-graph snapshot restore, and MCP hybrid ranking. This review did not rerun that coverage.']},
  {id:'persistence-must-be-explicit',title:'Persistence must be explicit',paragraphs:['Persistence may be disabled, unavailable, or unsuccessful. The runtime should distinguish those outcomes from a successful durable write rather than manufacturing a success message. The README describes opt-out settings for applicable paths.'],code:'ABI_WDBX_PERSIST=0\nABI_WDBX_PATH=:memory:',note:'These are documented configuration values, not commands that connect this website to WDBX. Their effect depends on the actual runtime path.'},
  {id:'verify-the-guarantee-you-need',title:'Verify the guarantee you need',paragraphs:['A storage recovery contract does not establish production distributed sharding, regulatory compliance, arbitrary scale, or a latency target. Evaluate the specific durability, isolation, recovery, and deployment behavior that matters to your application.','Consult the current WDBX specification and tests at the revision you will use. Record which behavior was checked and under what conditions. The conceptual explanations in this site should not be mistaken for versioned API documentation.']}
 ]},
 {slug:'identity',title:'Identity & governance',description:'Companion roles, capability boundaries, and a clear separation between style and authority.',group:'Systems',sources:['abi','identity'],sections:[
  {id:'separate-the-roles',title:'Separate the roles',paragraphs:['The ABI README describes Abbey as the primary empathetic-polymath profile, Aviva as the direct expert mode, and ABI as the orchestration and governance layer. These descriptions define interaction roles; they do not independently verify separate services or models.','The companion repository is linked by ABI, but its build and deployment were not assessed as part of this preview. Refer to current implementation evidence before assigning any concrete capability to a companion interface.']},
  {id:'style-does-not-grant-authority',title:'Style does not grant authority',paragraphs:['A warmer tone, expert mode, or recognizable identity should not be used as evidence that a system has credentials, access to private data, or permission to take external actions. Those properties need explicit configuration and authorization.','As a design principle, interfaces should make proposed actions, scope, and outcomes understandable. This principle is not a claim that a particular backend policy was verified by generating a website.']},
  {id:'keep-claims-inspectable',title:'Keep claims inspectable',paragraphs:['A claims ledger is useful only when a claim can be traced to evidence with a clear scope. An appealing personality is not evidence of consciousness, model quality, autonomy, or a persistent personal memory system.','Use the source identity specification for the project’s current mapping of implemented, partial, and proposed behavior. This page links that reference; it does not certify it.']}
 ]},
 {slug:'gama',title:'Gama framework',description:'A modular Swift UI framework organized around a retained render tree and explicit scenes.',group:'Systems',sources:['gama'],sections:[
  {id:'one-tree-several-hosts',title:'One tree, several hosts',paragraphs:['The Gama README describes a modular declarative UI framework written in Swift. A retained render tree connects application state and views to layout, drawing, and platform integrations.','The documented integrations include terminal, Apple, WebAssembly, C/Android, MLIR, and Embedded Swift surfaces. That list describes the project’s architecture; it is not a statement that this review ran every platform acceptance test.']},
  {id:'modules-with-clear-jobs',title:'Modules with clear jobs',paragraphs:['GamaCore contains scene, view, identity, state, layout, event, and FrameHost concepts. GamaTUI supplies a terminal backend, while GamaAppleUI provides an Apple host view. GamaWASM, GamaEmbed, and GamaMLIR cover other integration boundaries.','The README describes an explicit primary scene with optional auxiliary surfaces. Read its current migration notes before applying an older application example; a declarative API can change between project revisions.']},
  {id:'verify-your-target',title:'Verify your target',paragraphs:['Choose the host you need, read the actual module instructions, and run the relevant acceptance flow with the supported toolchain. Do not substitute a generic cross-platform claim for evidence on your target.','No installation command or language-version requirement is invented here. The upstream source is authoritative for setup. Keep measurements attached to their environment rather than treating a measurement harness as a performance guarantee.']}
 ]},
 {slug:'evidence',title:'Evidence & limitations',description:'A claim should tell you what supports it—and what remains outside its scope.',group:'Principles',sources:['abi','claims','platform'],sections:[
  {id:'two-independent-axes',title:'Two independent axes',paragraphs:['Implementation status and evidence provenance answer different questions. Current, partial, and proposed describe a capability’s lifecycle. Measured, reported, and target describe the provenance of a numerical figure in the existing MLAI contracts.','A reported capability is not necessarily a measured performance result. A target is not an achieved outcome. A synthetic example may be useful for explaining an interface, but it must not be presented as measurement.']},
  {id:'what-counts-as-evidence',title:'What counts as evidence',paragraphs:['A README can establish what a project documents. A test file can establish the conditions it is intended to exercise. A successful test run must identify its revision and environment. A meaningful benchmark needs more than an isolated number.'],bullets:['Identify the exact source revision and execution date.','Record hardware, toolchain, inputs, and relevant configuration.','Describe the method, uncertainty, and limitations.','Keep an artifact that another reader can inspect.']},
  {id:'what-this-site-does-not-prove',title:'What this site does not prove',paragraphs:['This website publishes no independently measured ABI, WDBX, or Gama performance results. It does not verify production deployments, regulatory certifications, general native GPU execution, or model intelligence.','A functional documentation search and an attractive architecture diagram are website features. They are not proof of the underlying projects’ runtime capabilities. The trust page intentionally labels source-documented behavior and the limitations that accompany it.']}
 ]},
 {slug:'platform',title:'Platform & site architecture',description:'The existing MLAI application, this isolated review, and their separate verification boundaries.',group:'Principles',sources:['platform','website'],sections:[
  {id:'an-existing-platform',title:'An existing platform',paragraphs:['MLAI-CORPORATION-WWW already exists. At the reviewed revision, apps/web contains the Quesar by MLAI website, while apps/mobile and apps/quasar have their own responsibilities and verification flows. The original greenfield assertion was incorrect.','The active web application is a Next.js TypeScript/TSX surface. Its README explicitly rejects reviving the old Vite, Hono, and Rust/Axum migration directions. This review does not modify or replace that app.']},
  {id:'separate-verification-boundaries',title:'Separate verification boundaries',paragraphs:['The repository retains app-specific lockfiles and check commands. A green web gate is not mobile evidence, a mobile export is not a signed device run, and a site-builder unit test is not a live provider generation.'],code:'bun run check:topology\nbun run check:web',note:'Run these only in the existing MLAI platform checkout after its documented setup. They are not this preview’s commands.'},
  {id:'this-review-build',title:'This review build',paragraphs:['This deliverable includes a self-contained review website and an isolated Next.js/React source candidate. The review is exported from shared TSX markup without installing Next or React; its browser checks do not verify framework hydration, bundling, or Fumadocs integration.','The Next source uses a small interactive boundary and Fumadocs MDX content loading. Dependency installation, a lockfile, full type-checking, the framework build, and deployment remain explicit integration gates. Nothing here changes production, DNS, credentials, or a GitHub branch.']}
 ]}
];
